-- 020_d78_notices.sql
-- D-78 P1 (docs/design/D78-SPEC.md 3.5, 6.1-6.2, D-80): information notices, their acceptance, the data controller of each
-- organization, and the extension of Consents for consent captured at registration.
--   * Notices: versioned texts (privacy notice, consent texts, the officer's attestation), one row per language; a text is never
--     edited after publishing, a new version retires the previous one. IsDraft marks texts not yet approved (O-14).
--   * NoticeAcceptances: append-only proof that a user (click or SMS code) or a beekeeper (SMS code or signed photo) accepted
--     a given version.
--   * Organizations: nullable data controller columns (name, address, contact, VERBİS number); empty on existing organizations.
--   * Consents: nullable Method, CodeId, NoticeId, RegisteringOrgId; AssociationOrgId and the document columns become nullable
--     (a consent confirmed by SMS has no document and may be given at a directorate). Widening only; existing rows unchanged.
--   * Seeds the DRAFT texts (version platform-2026-11-draft1) in five languages for review by the university's data-protection
--     office: the notice for users, the notice for beekeepers, the consent texts PublicName and PortalNotifications, and the
--     officer's attestation. Insert-only.
-- Additive and idempotent; a second run changes nothing. SQL Server 2019 (level 150). Run with sqlcmd -I -f 65001 (UTF-8).
-- BodySha256 = SHA-256 of the text as stored (nvarchar, UTF-16LE), lower-case hex; the application computes it the same way.

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

IF OBJECT_ID(N'dbo.Consents', N'U') IS NULL OR OBJECT_ID(N'dbo.OneTimeCodes', N'U') IS NULL
BEGIN
    RAISERROR(N'Run 008 and 019 first; aborting.', 16, 1);
    SET NOEXEC ON;
END;
GO

IF OBJECT_ID(N'dbo.Notices', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.Notices
    (
        NoticeId          int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Notices PRIMARY KEY,
        Kind              varchar(30)    NOT NULL,
        Audience          varchar(20)    NOT NULL,
        OrgId             int            NULL CONSTRAINT FK_Notices_Organizations REFERENCES dbo.Organizations (OrgId),
        Purpose           varchar(30)    NULL,
        Version           varchar(40)    NOT NULL,
        Language          varchar(5)     NOT NULL,
        Body              nvarchar(max)  NOT NULL,
        BodySha256        char(64)       NOT NULL,
        IsDraft           bit            NOT NULL CONSTRAINT DF_Notices_IsDraft DEFAULT (0),
        PublishedAt       datetime2      NOT NULL CONSTRAINT DF_Notices_PublishedAt DEFAULT (SYSUTCDATETIME()),
        PublishedByUserId nvarchar(450)  NULL,
        RetiredAt         datetime2      NULL,
        CONSTRAINT CK_Notices_Kind CHECK (Kind IN ('PrivacyNotice', 'ConsentText', 'TermsOfUse', 'Attestation')),
        CONSTRAINT CK_Notices_Audience CHECK (Audience IN ('Beekeeper', 'Member', 'All'))
    );
    CREATE UNIQUE INDEX UX_Notices_Version ON dbo.Notices (Kind, Audience, OrgId, Purpose, Version, Language);
END;
GO

IF OBJECT_ID(N'dbo.NoticeAcceptances', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.NoticeAcceptances
    (
        AcceptanceId           bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_NoticeAcceptances PRIMARY KEY,
        NoticeId               int            NOT NULL CONSTRAINT FK_NoticeAcceptances_Notices REFERENCES dbo.Notices (NoticeId),
        UserId                 nvarchar(450)  NULL,
        BeekeeperId            nvarchar(450)  NULL CONSTRAINT FK_NoticeAcceptances_Beekeepers REFERENCES dbo.Beekeepers (BeekeeperId),
        OrgId                  int            NULL,
        Method                 varchar(20)    NOT NULL,
        CodeId                 bigint         NULL CONSTRAINT FK_NoticeAcceptances_OneTimeCodes REFERENCES dbo.OneTimeCodes (CodeId),
        EvidenceStoredFileName nvarchar(100)  NULL,
        EvidenceSha256         char(64)       NULL,
        RecordedByUserId       nvarchar(450)  NOT NULL,
        At                     datetime2      NOT NULL CONSTRAINT DF_NoticeAcceptances_At DEFAULT (SYSUTCDATETIME()),
        ClientIp               varchar(45)    NULL,
        CONSTRAINT CK_NoticeAcceptances_Subject CHECK ((UserId IS NULL AND BeekeeperId IS NOT NULL) OR (UserId IS NOT NULL AND BeekeeperId IS NULL)),
        CONSTRAINT CK_NoticeAcceptances_Method CHECK (Method IN ('Click', 'SmsCode', 'SignedPhoto', 'Paper'))
    );
    CREATE INDEX IX_NoticeAcceptances_User ON dbo.NoticeAcceptances (UserId, NoticeId);
    CREATE INDEX IX_NoticeAcceptances_Beekeeper ON dbo.NoticeAcceptances (BeekeeperId, NoticeId);
END;
GO

CREATE OR ALTER TRIGGER dbo.TR_NoticeAcceptances_AppendOnly ON dbo.NoticeAcceptances AFTER UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM deleted)
        THROW 50001, N'NoticeAcceptances is append-only.', 1;
END;
GO

-- a published text never changes; only RetiredAt is set once
CREATE OR ALTER TRIGGER dbo.TR_Notices_Immutable ON dbo.Notices AFTER UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
        RETURN;
    IF NOT EXISTS (SELECT 1 FROM inserted)
        THROW 50001, N'Notices cannot be deleted; publish a new version instead.', 1;
    IF UPDATE(Kind) OR UPDATE(Audience) OR UPDATE(OrgId) OR UPDATE(Purpose) OR UPDATE(Version) OR UPDATE(Language)
       OR UPDATE(Body) OR UPDATE(BodySha256) OR UPDATE(IsDraft) OR UPDATE(PublishedAt) OR UPDATE(PublishedByUserId)
        THROW 50002, N'A published notice cannot be changed; publish a new version instead.', 1;
END;
GO

IF COL_LENGTH(N'dbo.Organizations', N'DataControllerName') IS NULL
    ALTER TABLE dbo.Organizations ADD
        DataControllerName    nvarchar(200) NULL,
        DataControllerAddress nvarchar(400) NULL,
        DataControllerContact nvarchar(200) NULL,
        VerbisNumber          nvarchar(50)  NULL;
GO

IF COL_LENGTH(N'dbo.Consents', N'Method') IS NULL
    ALTER TABLE dbo.Consents ADD
        Method           varchar(20) NULL,
        CodeId           bigint      NULL CONSTRAINT FK_Consents_OneTimeCodes REFERENCES dbo.OneTimeCodes (CodeId),
        NoticeId         int         NULL CONSTRAINT FK_Consents_Notices REFERENCES dbo.Notices (NoticeId),
        RegisteringOrgId int         NULL CONSTRAINT FK_Consents_RegisteringOrg REFERENCES dbo.Organizations (OrgId);
GO

-- widening: consents confirmed by SMS have no document and may be given at a directorate (no association)
IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.Consents') AND name = N'AssociationOrgId' AND is_nullable = 0)
    ALTER TABLE dbo.Consents ALTER COLUMN AssociationOrgId int NULL;
IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.Consents') AND name = N'DocumentStoredFileName' AND is_nullable = 0)
    ALTER TABLE dbo.Consents ALTER COLUMN DocumentStoredFileName nvarchar(100) NULL;
IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.Consents') AND name = N'DocumentOriginalFileName' AND is_nullable = 0)
    ALTER TABLE dbo.Consents ALTER COLUMN DocumentOriginalFileName nvarchar(260) NULL;
IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.Consents') AND name = N'DocumentSha256' AND is_nullable = 0)
    ALTER TABLE dbo.Consents ALTER COLUMN DocumentSha256 char(64) NULL;
GO

BEGIN TRANSACTION;

DECLARE @n TABLE (Kind varchar(30) NOT NULL, Audience varchar(20) NOT NULL, Purpose varchar(30) NULL, Version varchar(40) NOT NULL,
                  Language varchar(5) NOT NULL, Body nvarchar(max) NOT NULL);
INSERT @n (Kind, Audience, Purpose, Version, Language, Body) VALUES
    ('PrivacyNotice', 'Member', NULL, 'platform-2026-11-draft1', 'en', REPLACE(N'DRAFT for review by the university''s data-protection office. This text is not yet approved.|NL||NL|Privacy notice for the users of TOP4HoneyChains|NL||NL|Who is responsible. Each organization you work for is the data controller of the records you enter on its behalf; its name and contact are shown with this notice. The platform operator (the TOP4HoneyChains project, INTALA Lab, Işık University) is the controller of your user account, the audit log, the SMS log and the public pages, and processes the organizations'' records on their behalf.|NL||NL|What is processed. Your user name, mobile phone number and e-mail address (if given), your memberships and roles, the records you enter, approve or read, and the time and network address of each change (audit log).|NL||NL|Why. To give you access to the platform (contract); to record who did what in the food traceability chain (legal obligation: Food Law No. 5996 and Regulation (EC) No 178/2002, Article 18); to send you sign-in details and one-time codes by SMS (necessary for the service); to protect the platform against misuse (legitimate interest).|NL||NL|Who receives it. Other organizations in the chain see your name only where a record shows who entered or approved it. The SMS provider receives your phone number and the text of each message. Nothing is sold or used for advertising.|NL||NL|Where. The data is stored on servers in Türkiye. If this changes, a new version of this notice will say so before the change.|NL||NL|How long (proposal). Your account: until two years after your last membership ends. Audit entries: ten years. SMS records: one year. One-time codes: thirty days.|NL||NL|Your rights (KVKK Article 11, GDPR Articles 15 to 22). You can ask what is held about you, have it corrected, ask for its deletion where no legal obligation requires keeping it, and object to processing. Write to the data controller of your organization (contact shown with this notice) or to the platform operator.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Member', NULL, 'platform-2026-11-draft1', 'tr', REPLACE(N'TASLAK: Üniversitenin kişisel verilerin korunması birimi tarafından incelenecektir. Bu metin henüz onaylanmamıştır.|NL||NL|TOP4HoneyChains kullanıcıları için aydınlatma metni|NL||NL|Veri sorumlusu. Adına çalıştığınız her kuruluş, o kuruluş adına girdiğiniz kayıtların veri sorumlusudur; kuruluşun adı ve iletişim bilgileri bu metinle birlikte gösterilir. Platform işletmecisi (TOP4HoneyChains projesi, INTALA Lab, Işık Üniversitesi) kullanıcı hesabınızın, denetim kaydının, SMS kaydının ve herkese açık sayfaların veri sorumlusudur ve kuruluşların kayıtlarını onlar adına işler.|NL||NL|İşlenen veriler. Kullanıcı adınız, cep telefonu numaranız ve (verilmişse) e-posta adresiniz, üyelikleriniz ve rolleriniz, girdiğiniz, onayladığınız veya okuduğunuz kayıtlar ile her değişikliğin zamanı ve ağ adresi (denetim kaydı).|NL||NL|Amaç ve hukuki sebep. Platforma erişiminizi sağlamak (sözleşme); gıda izlenebilirlik zincirinde kimin ne yaptığını kaydetmek (hukuki yükümlülük: 5996 sayılı Kanun ve 178/2002 sayılı AB Tüzüğü, madde 18); giriş bilgilerinizi ve tek kullanımlık kodları SMS ile göndermek (hizmetin gereği); platformu kötüye kullanıma karşı korumak (meşru menfaat).|NL||NL|Aktarılan taraflar. Zincirdeki diğer kuruluşlar adınızı yalnızca bir kaydı kimin girdiğini veya onayladığını gösteren yerlerde görür. SMS sağlayıcısı telefon numaranızı ve her mesajın metnini alır. Veriler satılmaz ve reklam için kullanılmaz.|NL||NL|Saklama yeri. Veriler Türkiye''deki sunucularda saklanır. Bu değişirse, değişiklikten önce bu metnin yeni bir sürümü bunu belirtir.|NL||NL|Saklama süresi (öneri). Hesabınız: son üyeliğiniz bittikten iki yıl sonrasına kadar. Denetim kayıtları: on yıl. SMS kayıtları: bir yıl. Tek kullanımlık kodlar: otuz gün.|NL||NL|Haklarınız (KVKK madde 11). Hakkınızda hangi verilerin tutulduğunu öğrenebilir, düzeltilmesini, yasal bir saklama yükümlülüğü yoksa silinmesini isteyebilir ve işlemeye itiraz edebilirsiniz. Kuruluşunuzun veri sorumlusuna (iletişim bilgisi bu metinle birlikte gösterilir) veya platform işletmecisine yazın.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Member', NULL, 'platform-2026-11-draft1', 'es', REPLACE(N'BORRADOR para revisión por la oficina de protección de datos de la universidad. Este texto aún no está aprobado.|NL||NL|Aviso de privacidad para los usuarios de TOP4HoneyChains|NL||NL|Responsable. Cada organización para la que trabaja es responsable de los registros que usted introduce en su nombre; su nombre y contacto se muestran junto con este aviso. El operador de la plataforma (el proyecto TOP4HoneyChains, INTALA Lab, Universidad Işık) es responsable de su cuenta de usuario, del registro de auditoría, del registro de SMS y de las páginas públicas, y trata los registros de las organizaciones por cuenta de ellas.|NL||NL|Qué datos se tratan. Su nombre de usuario, su número de teléfono móvil y su correo electrónico (si lo da), sus membresías y roles, los registros que introduce, aprueba o consulta, y la hora y la dirección de red de cada cambio (registro de auditoría).|NL||NL|Para qué. Para darle acceso a la plataforma (contrato); para registrar quién hizo qué en la cadena de trazabilidad alimentaria (obligación legal: Ley turca n.º 5996 y Reglamento (CE) n.º 178/2002, artículo 18); para enviarle por SMS los datos de acceso y códigos de un solo uso (necesario para el servicio); para proteger la plataforma contra el uso indebido (interés legítimo).|NL||NL|Quién los recibe. Otras organizaciones de la cadena ven su nombre solo donde un registro muestra quién lo introdujo o aprobó. El proveedor de SMS recibe su número de teléfono y el texto de cada mensaje. Nada se vende ni se usa con fines publicitarios.|NL||NL|Dónde. Los datos se guardan en servidores en Türkiye. Si esto cambia, una nueva versión de este aviso lo indicará antes del cambio.|NL||NL|Durante cuánto tiempo (propuesta). Su cuenta: hasta dos años después del fin de su última membresía. Registros de auditoría: diez años. Registros de SMS: un año. Códigos de un solo uso: treinta días.|NL||NL|Sus derechos (RGPD, artículos 15 a 22; KVKK, artículo 11). Puede saber qué datos se guardan sobre usted, pedir su rectificación, su supresión cuando ninguna obligación legal exija conservarlos, y oponerse al tratamiento. Escriba al responsable de su organización (contacto junto a este aviso) o al operador de la plataforma.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Member', NULL, 'platform-2026-11-draft1', 'pl', REPLACE(N'PROJEKT do weryfikacji przez uczelniany zespół ochrony danych. Ten tekst nie jest jeszcze zatwierdzony.|NL||NL|Informacja o przetwarzaniu danych dla użytkowników TOP4HoneyChains|NL||NL|Administrator. Każda organizacja, dla której pracujesz, jest administratorem danych w rekordach wprowadzanych w jej imieniu; jej nazwa i dane kontaktowe są pokazane obok tej informacji. Operator platformy (projekt TOP4HoneyChains, INTALA Lab, Uniwersytet Işık) jest administratorem Twojego konta, dziennika audytu, rejestru SMS i stron publicznych oraz przetwarza rekordy organizacji w ich imieniu.|NL||NL|Jakie dane. Nazwa użytkownika, numer telefonu komórkowego i adres e-mail (jeśli podany), członkostwa i role, rekordy, które wprowadzasz, zatwierdzasz lub odczytujesz, oraz czas i adres sieciowy każdej zmiany (dziennik audytu).|NL||NL|W jakim celu. Aby zapewnić dostęp do platformy (umowa); aby rejestrować, kto co zrobił w łańcuchu identyfikowalności żywności (obowiązek prawny: turecka ustawa nr 5996 i rozporządzenie (WE) nr 178/2002, art. 18); aby wysyłać SMS z danymi logowania i kodami jednorazowymi (niezbędne do świadczenia usługi); aby chronić platformę przed nadużyciami (prawnie uzasadniony interes).|NL||NL|Odbiorcy. Inne organizacje w łańcuchu widzą Twoje imię i nazwisko tylko tam, gdzie rekord pokazuje, kto go wprowadził lub zatwierdził. Dostawca SMS otrzymuje Twój numer telefonu i treść każdej wiadomości. Dane nie są sprzedawane ani wykorzystywane do reklamy.|NL||NL|Gdzie. Dane są przechowywane na serwerach w Turcji. Jeśli to się zmieni, nowa wersja tej informacji poinformuje o tym przed zmianą.|NL||NL|Jak długo (propozycja). Konto: do dwóch lat po zakończeniu ostatniego członkostwa. Wpisy audytu: dziesięć lat. Rejestr SMS: rok. Kody jednorazowe: trzydzieści dni.|NL||NL|Twoje prawa (RODO, art. 15–22; KVKK, art. 11). Możesz zapytać, jakie dane są o Tobie przechowywane, żądać ich sprostowania, usunięcia, jeśli żaden obowiązek prawny nie wymaga ich przechowywania, oraz wnieść sprzeciw. Napisz do administratora swojej organizacji (kontakt obok tej informacji) lub do operatora platformy.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Member', NULL, 'platform-2026-11-draft1', 'lv', REPLACE(N'PROJEKTS, ko pārskatīs universitātes datu aizsardzības nodaļa. Šis teksts vēl nav apstiprināts.|NL||NL|Privātuma paziņojums TOP4HoneyChains lietotājiem|NL||NL|Pārzinis. Katra organizācija, kuras vārdā strādājat, ir to ierakstu pārzinis, ko ievadāt tās vārdā; tās nosaukums un kontaktinformācija ir parādīta kopā ar šo paziņojumu. Platformas operators (projekts TOP4HoneyChains, INTALA Lab, Işık universitāte) ir jūsu lietotāja konta, audita žurnāla, SMS žurnāla un publisko lapu pārzinis un apstrādā organizāciju ierakstus to vārdā.|NL||NL|Kādi dati. Jūsu lietotājvārds, mobilā tālruņa numurs un e-pasta adrese (ja norādīta), jūsu dalības un lomas, ieraksti, ko ievadāt, apstiprināt vai lasāt, kā arī katras izmaiņas laiks un tīkla adrese (audita žurnāls).|NL||NL|Kāpēc. Lai dotu jums piekļuvi platformai (līgums); lai reģistrētu, kas ko darīja pārtikas izsekojamības ķēdē (juridisks pienākums: Turcijas likums Nr. 5996 un Regula (EK) Nr. 178/2002, 18. pants); lai sūtītu jums pieteikšanās datus un vienreizējus kodus pa SMS (nepieciešams pakalpojumam); lai aizsargātu platformu pret ļaunprātīgu izmantošanu (leģitīmās intereses).|NL||NL|Saņēmēji. Citas ķēdes organizācijas redz jūsu vārdu tikai tur, kur ieraksts rāda, kas to ievadīja vai apstiprināja. SMS pakalpojumu sniedzējs saņem jūsu tālruņa numuru un katras ziņas tekstu. Dati netiek pārdoti un netiek izmantoti reklāmai.|NL||NL|Kur. Dati tiek glabāti serveros Turcijā. Ja tas mainīsies, jauna šī paziņojuma versija par to pateiks pirms izmaiņām.|NL||NL|Cik ilgi (priekšlikums). Jūsu konts: līdz diviem gadiem pēc pēdējās dalības beigām. Audita ieraksti: desmit gadi. SMS ieraksti: viens gads. Vienreizējie kodi: trīsdesmit dienas.|NL||NL|Jūsu tiesības (VDAR 15.–22. pants; KVKK 11. pants). Jūs varat uzzināt, kādi dati par jums tiek glabāti, pieprasīt to labošanu, dzēšanu, ja nekāds juridisks pienākums neprasa tos glabāt, un iebilst pret apstrādi. Rakstiet savas organizācijas pārzinim (kontakts kopā ar šo paziņojumu) vai platformas operatoram.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Beekeeper', NULL, 'platform-2026-11-draft1', 'en', REPLACE(N'DRAFT for review by the university''s data-protection office. This text is not yet approved.|NL||NL|Privacy notice for beekeepers registered in TOP4HoneyChains|NL||NL|Who is responsible. The district directorate that registers you is the data controller of your registration. The plants you deliver honey to are the controllers of your deliveries. The platform operator (the TOP4HoneyChains project, INTALA Lab, Işık University) runs the platform for them and is responsible for the public pages.|NL||NL|What is processed. Your name, birth date, mobile phone number, beekeeping registry number, education and type of beekeeping; your apiaries with their location and number of hives; your deliveries, the samples taken from them and their laboratory results; the batches that contain your honey.|NL||NL|Why. To register you as a beekeeper and verify your registry number; to trace honey from your apiary to the jar, as food law requires (Food Law No. 5996, Regulation (EC) No 178/2002, Article 18); to confirm registrations and deliveries with a code sent to your phone.|NL||NL|Who receives it. The plants you deliver to and the laboratories that analyse your samples see the records they work with. Your association sees its member beekeepers. Public pages show the province of your honey and its laboratory results; your name is shown there only if you agree (separate consent). The exact location of your apiaries and your phone number are never public. The SMS provider receives your phone number and the text of each message.|NL||NL|Where. The data is stored on servers in Türkiye.|NL||NL|How long (proposal). Delivery and laboratory records: five years after the best-before date of the last batch that contains them; then your name is replaced by a code. Signed forms: as long as the record they prove. SMS records: one year.|NL||NL|Your rights (KVKK Article 11). You can ask what is held about you, have it corrected, ask for its deletion where food law does not require keeping it, object, and withdraw any consent at any time. Contact the directorate that registered you or the platform operator.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Beekeeper', NULL, 'platform-2026-11-draft1', 'tr', REPLACE(N'TASLAK: Üniversitenin kişisel verilerin korunması birimi tarafından incelenecektir. Bu metin henüz onaylanmamıştır.|NL||NL|TOP4HoneyChains''e kayıtlı arıcılar için aydınlatma metni|NL||NL|Veri sorumlusu. Sizi kaydeden ilçe müdürlüğü kaydınızın veri sorumlusudur. Bal teslim ettiğiniz işletmeler teslimatlarınızın veri sorumlusudur. Platform işletmecisi (TOP4HoneyChains projesi, INTALA Lab, Işık Üniversitesi) platformu onlar için işletir ve herkese açık sayfalardan sorumludur.|NL||NL|İşlenen veriler. Adınız, doğum tarihiniz, cep telefonu numaranız, arıcılık kayıt numaranız, eğitim durumunuz ve arıcılık türünüz; arılıklarınız, konumları ve kovan sayıları; teslimatlarınız, bunlardan alınan numuneler ve analiz sonuçları; balınızın bulunduğu partiler.|NL||NL|Amaç ve hukuki sebep. Sizi arıcı olarak kaydetmek ve kayıt numaranızı doğrulamak; gıda mevzuatının gerektirdiği şekilde balı arılığınızdan kavanoza kadar izlemek (5996 sayılı Kanun, 178/2002 sayılı AB Tüzüğü madde 18); kayıtları ve teslimatları telefonunuza gönderilen bir kodla onaylamak.|NL||NL|Aktarılan taraflar. Bal teslim ettiğiniz işletmeler ve numunelerinizi analiz eden laboratuvarlar, çalıştıkları kayıtları görür. Birliğiniz üye arıcılarını görür. Herkese açık sayfalar balınızın ilini ve analiz sonuçlarını gösterir; adınız yalnızca onay verirseniz gösterilir (ayrı rıza). Arılıklarınızın tam konumu ve telefon numaranız hiçbir zaman herkese açık değildir. SMS sağlayıcısı telefon numaranızı ve her mesajın metnini alır.|NL||NL|Saklama yeri. Veriler Türkiye''deki sunucularda saklanır.|NL||NL|Saklama süresi (öneri). Teslimat ve analiz kayıtları: bunları içeren son partinin son tüketim tarihinden beş yıl sonrasına kadar; ardından adınız bir kodla değiştirilir. İmzalı formlar: kanıtladıkları kayıt kadar. SMS kayıtları: bir yıl.|NL||NL|Haklarınız (KVKK madde 11). Hakkınızda hangi verilerin tutulduğunu öğrenebilir, düzeltilmesini, gıda mevzuatı saklamayı gerektirmiyorsa silinmesini isteyebilir, itiraz edebilir ve verdiğiniz rızayı her zaman geri alabilirsiniz. Sizi kaydeden müdürlüğe veya platform işletmecisine başvurun.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Beekeeper', NULL, 'platform-2026-11-draft1', 'es', REPLACE(N'BORRADOR para revisión por la oficina de protección de datos de la universidad. Este texto aún no está aprobado.|NL||NL|Aviso de privacidad para los apicultores registrados en TOP4HoneyChains|NL||NL|Responsable. La dirección distrital que le registra es responsable de su registro. Las plantas a las que entrega miel son responsables de sus entregas. El operador de la plataforma (el proyecto TOP4HoneyChains, INTALA Lab, Universidad Işık) gestiona la plataforma para ellas y es responsable de las páginas públicas.|NL||NL|Qué datos se tratan. Su nombre, fecha de nacimiento, número de teléfono móvil, número de registro apícola, nivel de estudios y tipo de apicultura; sus colmenares con su ubicación y número de colmenas; sus entregas, las muestras tomadas de ellas y sus resultados de laboratorio; las partidas que contienen su miel.|NL||NL|Para qué. Para registrarle como apicultor y verificar su número de registro; para seguir la miel desde su colmenar hasta el frasco, como exige la legislación alimentaria (Ley turca n.º 5996, Reglamento (CE) n.º 178/2002, artículo 18); para confirmar registros y entregas con un código enviado a su teléfono.|NL||NL|Quién los recibe. Las plantas a las que entrega y los laboratorios que analizan sus muestras ven los registros con los que trabajan. Su asociación ve a sus apicultores miembros. Las páginas públicas muestran la provincia de su miel y sus resultados de laboratorio; su nombre solo aparece si usted lo acepta (consentimiento aparte). La ubicación exacta de sus colmenares y su teléfono nunca son públicos. El proveedor de SMS recibe su número y el texto de cada mensaje.|NL||NL|Dónde. Los datos se guardan en servidores en Türkiye.|NL||NL|Durante cuánto tiempo (propuesta). Registros de entregas y de laboratorio: cinco años después de la fecha de consumo preferente de la última partida que los contiene; después su nombre se sustituye por un código. Formularios firmados: mientras exista el registro que prueban. Registros de SMS: un año.|NL||NL|Sus derechos (KVKK, artículo 11). Puede saber qué datos se guardan sobre usted, pedir su rectificación, su supresión cuando la legislación alimentaria no exija conservarlos, oponerse y retirar cualquier consentimiento en cualquier momento. Diríjase a la dirección que le registró o al operador de la plataforma.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Beekeeper', NULL, 'platform-2026-11-draft1', 'pl', REPLACE(N'PROJEKT do weryfikacji przez uczelniany zespół ochrony danych. Ten tekst nie jest jeszcze zatwierdzony.|NL||NL|Informacja o przetwarzaniu danych dla pszczelarzy zarejestrowanych w TOP4HoneyChains|NL||NL|Administrator. Powiatowa dyrekcja, która Cię rejestruje, jest administratorem danych rejestracji. Zakłady, do których dostarczasz miód, są administratorami danych dostaw. Operator platformy (projekt TOP4HoneyChains, INTALA Lab, Uniwersytet Işık) prowadzi platformę dla nich i odpowiada za strony publiczne.|NL||NL|Jakie dane. Imię i nazwisko, data urodzenia, numer telefonu komórkowego, numer w rejestrze pszczelarskim, wykształcenie i rodzaj pszczelarstwa; pasieki z ich położeniem i liczbą uli; dostawy, pobrane z nich próbki i wyniki laboratoryjne; partie zawierające Twój miód.|NL||NL|W jakim celu. Aby zarejestrować Cię jako pszczelarza i zweryfikować numer w rejestrze; aby śledzić miód od pasieki do słoika, jak wymaga prawo żywnościowe (turecka ustawa nr 5996, rozporządzenie (WE) nr 178/2002, art. 18); aby potwierdzać rejestracje i dostawy kodem wysłanym na Twój telefon.|NL||NL|Odbiorcy. Zakłady, do których dostarczasz miód, i laboratoria badające Twoje próbki widzą rekordy, z którymi pracują. Twoje stowarzyszenie widzi swoich członków. Strony publiczne pokazują prowincję pochodzenia miodu i wyniki badań; Twoje imię i nazwisko jest tam pokazane tylko za Twoją zgodą (osobna zgoda). Dokładne położenie pasiek i numer telefonu nigdy nie są publiczne. Dostawca SMS otrzymuje Twój numer i treść każdej wiadomości.|NL||NL|Gdzie. Dane są przechowywane na serwerach w Turcji.|NL||NL|Jak długo (propozycja). Rekordy dostaw i badań: pięć lat po dacie minimalnej trwałości ostatniej partii, która je zawiera; potem imię i nazwisko zastępuje kod. Podpisane formularze: tak długo jak rekord, którego dowodzą. Rejestr SMS: rok.|NL||NL|Twoje prawa (KVKK, art. 11). Możesz zapytać, jakie dane są o Tobie przechowywane, żądać ich sprostowania, usunięcia, jeśli prawo żywnościowe nie wymaga ich przechowywania, wnieść sprzeciw i w każdej chwili wycofać zgodę. Zwróć się do dyrekcji, która Cię zarejestrowała, lub do operatora platformy.', N'|NL|', NCHAR(10))),
    ('PrivacyNotice', 'Beekeeper', NULL, 'platform-2026-11-draft1', 'lv', REPLACE(N'PROJEKTS, ko pārskatīs universitātes datu aizsardzības nodaļa. Šis teksts vēl nav apstiprināts.|NL||NL|Privātuma paziņojums TOP4HoneyChains reģistrētajiem biškopjiem|NL||NL|Pārzinis. Novada pārvalde, kas jūs reģistrē, ir jūsu reģistrācijas pārzinis. Uzņēmumi, kuriem piegādājat medu, ir jūsu piegāžu pārziņi. Platformas operators (projekts TOP4HoneyChains, INTALA Lab, Işık universitāte) uztur platformu to vārdā un atbild par publiskajām lapām.|NL||NL|Kādi dati. Jūsu vārds, dzimšanas datums, mobilā tālruņa numurs, biškopības reģistra numurs, izglītība un biškopības veids; jūsu dravas ar to atrašanās vietu un stropu skaitu; jūsu piegādes, no tām ņemtie paraugi un to laboratorijas rezultāti; partijas, kurās ir jūsu medus.|NL||NL|Kāpēc. Lai reģistrētu jūs kā biškopi un pārbaudītu jūsu reģistra numuru; lai izsekotu medu no jūsu dravas līdz burkai, kā to prasa pārtikas tiesību akti (Turcijas likums Nr. 5996, Regula (EK) Nr. 178/2002, 18. pants); lai apstiprinātu reģistrācijas un piegādes ar kodu, kas nosūtīts uz jūsu tālruni.|NL||NL|Saņēmēji. Uzņēmumi, kuriem piegādājat medu, un laboratorijas, kas analizē jūsu paraugus, redz ierakstus, ar kuriem strādā. Jūsu biedrība redz savus biedrus. Publiskās lapas rāda jūsu medus provinci un laboratorijas rezultātus; jūsu vārds tur tiek rādīts tikai ar jūsu piekrišanu (atsevišķa piekrišana). Precīza dravu atrašanās vieta un jūsu tālruņa numurs nekad nav publiski. SMS pakalpojumu sniedzējs saņem jūsu numuru un katras ziņas tekstu.|NL||NL|Kur. Dati tiek glabāti serveros Turcijā.|NL||NL|Cik ilgi (priekšlikums). Piegāžu un laboratorijas ieraksti: piecus gadus pēc pēdējās tos saturošās partijas minimālā derīguma termiņa; pēc tam jūsu vārdu aizstāj ar kodu. Parakstītās veidlapas: tik ilgi, kamēr pastāv ieraksts, ko tās pierāda. SMS ieraksti: viens gads.|NL||NL|Jūsu tiesības (KVKK 11. pants). Jūs varat uzzināt, kādi dati par jums tiek glabāti, pieprasīt to labošanu, dzēšanu, ja pārtikas tiesību akti neprasa tos glabāt, iebilst un jebkurā laikā atsaukt jebkuru piekrišanu. Vērsieties pārvaldē, kas jūs reģistrēja, vai pie platformas operatora.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PublicName', 'platform-2026-11-draft1', 'en', REPLACE(N'DRAFT for review by the university''s data-protection office.|NL||NL|Consent: my name on public pages. I agree that my first and last name are shown on the public pages of TOP4HoneyChains: the Honey Story of the batches that contain my honey and my beekeeper page. Without this consent a neutral code is shown instead of my name. I can withdraw this consent at any time; my name then disappears from the public pages at once.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PublicName', 'platform-2026-11-draft1', 'tr', REPLACE(N'TASLAK: Üniversitenin kişisel verilerin korunması birimi tarafından incelenecektir.|NL||NL|Açık rıza: adımın herkese açık sayfalarda gösterilmesi. Adımın ve soyadımın TOP4HoneyChains''in herkese açık sayfalarında, yani balımı içeren partilerin Bal Hikâyesi''nde ve arıcı sayfamda gösterilmesine onay veriyorum. Bu rıza olmadan adım yerine nötr bir kod gösterilir. Bu rızayı her zaman geri alabilirim; adım o anda herkese açık sayfalardan kalkar.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PublicName', 'platform-2026-11-draft1', 'es', REPLACE(N'BORRADOR para revisión por la oficina de protección de datos de la universidad.|NL||NL|Consentimiento: mi nombre en las páginas públicas. Acepto que mi nombre y apellidos se muestren en las páginas públicas de TOP4HoneyChains: la Historia de la Miel de las partidas que contienen mi miel y mi página de apicultor. Sin este consentimiento se muestra un código neutro en lugar de mi nombre. Puedo retirar este consentimiento en cualquier momento; mi nombre desaparece entonces de inmediato de las páginas públicas.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PublicName', 'platform-2026-11-draft1', 'pl', REPLACE(N'PROJEKT do weryfikacji przez uczelniany zespół ochrony danych.|NL||NL|Zgoda: moje imię i nazwisko na stronach publicznych. Zgadzam się, aby moje imię i nazwisko były pokazywane na stronach publicznych TOP4HoneyChains: w Historii Miodu partii zawierających mój miód i na mojej stronie pszczelarza. Bez tej zgody zamiast mojego imienia i nazwiska pokazywany jest neutralny kod. Mogę wycofać tę zgodę w każdej chwili; moje imię i nazwisko znika wtedy natychmiast ze stron publicznych.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PublicName', 'platform-2026-11-draft1', 'lv', REPLACE(N'PROJEKTS, ko pārskatīs universitātes datu aizsardzības nodaļa.|NL||NL|Piekrišana: mans vārds publiskajās lapās. Es piekrītu, ka mans vārds un uzvārds tiek rādīts TOP4HoneyChains publiskajās lapās: to partiju Medus stāstā, kurās ir mans medus, un manā biškopja lapā. Bez šīs piekrišanas mana vārda vietā tiek rādīts neitrāls kods. Es varu jebkurā laikā atsaukt šo piekrišanu; tad mans vārds uzreiz pazūd no publiskajām lapām.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PortalNotifications', 'platform-2026-11-draft1', 'en', REPLACE(N'DRAFT for review by the university''s data-protection office.|NL||NL|Consent: SMS notifications. I agree to receive SMS messages about my deliveries and laboratory results, in addition to the codes and sign-in details that the service needs. I can withdraw this consent at any time.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PortalNotifications', 'platform-2026-11-draft1', 'tr', REPLACE(N'TASLAK: Üniversitenin kişisel verilerin korunması birimi tarafından incelenecektir.|NL||NL|Açık rıza: SMS bildirimleri. Hizmetin gerektirdiği kodlar ve giriş bilgilerine ek olarak, teslimatlarım ve analiz sonuçlarım hakkında SMS almayı kabul ediyorum. Bu rızayı her zaman geri alabilirim.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PortalNotifications', 'platform-2026-11-draft1', 'es', REPLACE(N'BORRADOR para revisión por la oficina de protección de datos de la universidad.|NL||NL|Consentimiento: avisos por SMS. Acepto recibir SMS sobre mis entregas y resultados de laboratorio, además de los códigos y datos de acceso que el servicio necesita. Puedo retirar este consentimiento en cualquier momento.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PortalNotifications', 'platform-2026-11-draft1', 'pl', REPLACE(N'PROJEKT do weryfikacji przez uczelniany zespół ochrony danych.|NL||NL|Zgoda: powiadomienia SMS. Zgadzam się otrzymywać SMS o moich dostawach i wynikach badań, oprócz kodów i danych logowania potrzebnych do usługi. Mogę wycofać tę zgodę w każdej chwili.', N'|NL|', NCHAR(10))),
    ('ConsentText', 'Beekeeper', 'PortalNotifications', 'platform-2026-11-draft1', 'lv', REPLACE(N'PROJEKTS, ko pārskatīs universitātes datu aizsardzības nodaļa.|NL||NL|Piekrišana: SMS paziņojumi. Es piekrītu saņemt SMS par savām piegādēm un laboratorijas rezultātiem papildus kodiem un pieteikšanās datiem, kas vajadzīgi pakalpojumam. Es varu jebkurā laikā atsaukt šo piekrišanu.', N'|NL|', NCHAR(10))),
    ('Attestation', 'Member', NULL, 'attestation-2026-11-draft1', 'en', REPLACE(N'I have seen the beekeeper''s identity document and the registry record of the beekeeping enterprise, and the beekeeper has read or heard the information notice before giving the code or signing.', N'|NL|', NCHAR(10))),
    ('Attestation', 'Member', NULL, 'attestation-2026-11-draft1', 'tr', REPLACE(N'Arıcının kimlik belgesini ve arıcılık işletmesinin kayıt bilgisini gördüm; arıcı, kodu vermeden veya imzalamadan önce aydınlatma metnini okudu ya da dinledi.', N'|NL|', NCHAR(10))),
    ('Attestation', 'Member', NULL, 'attestation-2026-11-draft1', 'es', REPLACE(N'He visto el documento de identidad del apicultor y el registro de la explotación apícola, y el apicultor ha leído o escuchado el aviso de privacidad antes de dar el código o firmar.', N'|NL|', NCHAR(10))),
    ('Attestation', 'Member', NULL, 'attestation-2026-11-draft1', 'pl', REPLACE(N'Okazano mi dokument tożsamości pszczelarza i wpis gospodarstwa pasiecznego w rejestrze, a informacja o przetwarzaniu danych została pszczelarzowi przedstawiona (do przeczytania lub odczytana) przed podaniem kodu lub podpisaniem.', N'|NL|', NCHAR(10))),
    ('Attestation', 'Member', NULL, 'attestation-2026-11-draft1', 'lv', REPLACE(N'Man tika uzrādīts biškopja personu apliecinošs dokuments un biškopības saimniecības reģistra ieraksts, un privātuma paziņojums biškopim tika dots izlasīt vai nolasīts pirms koda sniegšanas vai parakstīšanas.', N'|NL|', NCHAR(10)));

INSERT dbo.Notices (Kind, Audience, OrgId, Purpose, Version, Language, Body, BodySha256, IsDraft)
SELECT n.Kind, n.Audience, NULL, n.Purpose, n.Version, n.Language, n.Body,
       LOWER(CONVERT(char(64), HASHBYTES('SHA2_256', n.Body), 2)), 1
FROM @n n
WHERE NOT EXISTS (SELECT 1 FROM dbo.Notices x
                  WHERE x.Kind = n.Kind AND x.Audience = n.Audience AND x.OrgId IS NULL AND ISNULL(x.Purpose, '') = ISNULL(n.Purpose, '')
                    AND x.Version = n.Version AND x.Language = n.Language);

COMMIT TRANSACTION;

PRINT N'020: Notices, NoticeAcceptances, data controller columns and consent columns are in place; draft texts seeded.';
GO

SET NOEXEC OFF;
GO
